import {readFileSync} from 'node:fs';
import {Pool} from 'pg';
import {createLeaseIssuer,EmailOutbox} from '@waitron-cloud/registration';
import {startAccountServer} from '../../src/server.ts';
const {schema,applicationName,issuerKey,config,origin,keys,rateKey}=JSON.parse(readFileSync(0,'utf8'));
const pool=new Pool({connectionString:process.env.TEST_DATABASE_URL,application_name:applicationName??schema,options:`-c search_path=${schema} -c statement_timeout=10000`});
const running=await startAccountServer({pool,outbox:new EmailOutbox({activeKeyId:'test',keys}),config:{portalOrigin:origin,production:false,rateKey,trustedProxyIps:[]},port:0,leaseIssuer:createLeaseIssuer(issuerKey),...(config?{relay:{...config,grants:{...config.grants,verifyOrigin:async()=>{throw Error('no reapproval');}}}}:{})});
const address=running.server.address();if(!address||typeof address==='string')throw Error('no HTTP port');
process.stdout.write(JSON.stringify({port:address.port})+'\n');
process.once('SIGTERM',()=>{void running.close().then(()=>pool.end());});
